  const planes = [fixed, fixed + out];
  const fp = axis === "x"
    ? [lo, y0 - 1, Math.min(...planes), hi, y1, Math.max(...planes)]
    : [Math.min(...planes), y0 - 1, lo, Math.max(...planes), y1, hi];
