export function lampPost(g, x, z, h, opts = {}) {
  const fp = [x, 1, z, x, h + 1, z];
  let n = 0;
  for (let y = 1; y <= h; y++) n += put(g, fp, [x, y, z], "spruce_fence", FENCE_POST, opts);
